const message = ($json.body.message || '').toLowerCase();
let reply = '';
let chips = [];

if (message.includes('kayu') || message.includes('shelter') || message.includes('teduh') || message.includes('tenda')) {
  reply = 'Kamu berhasil mengumpulkan 8 dahan kayu kokoh dan daun palem lebar. Sebuah tenda bivak darurat selesai dibangun di bawah dinding tebing batu! (Stamina -15, Proteksi Badai +80%).';
  chips = ['Nyalakan api unggun di depan bivak', 'Cari sumber makanan darurat', 'Istirahat sejenak pulihkan stamina'];
} else if (message.includes('kelapa') || message.includes('air') || message.includes('makan') || message.includes('minum')) {
  reply = 'Kamu memanjat pohon kelapa landai dan memetik 2 buah kelapa muda segar serta menemukan mata air jernih. Dahaga dan rasa laparmu teratasi! (Stamina +35, Rasa Lapar 0%).';
  chips = ['Bangun tempat berteduh darurat', 'Buat sinyal SOS di pasir pantai', 'Eksplorasi ke dalam hutan'];
} else if (message.includes('api') || message.includes('unggun')) {
  reply = 'Menggunakan batu rijang dan serat sabut kelapa kering, percikan api menyala! Api unggun hangat berkobar mengusir serangga dan binatang malam.';
  chips = ['Panggang makanan di atas api', 'Jaga api tetap menyala', 'Buat obor penjelajah'];
} else {
  reply = `Aksi survival: \"${$json.body.message}\". Angin laut berhembus makin kencang membawa aroma hujan badai. Keputusanmu menentukan kelangsungan hidupmu malam ini.`;
  chips = ['Cari perlindungan di gua karang', 'Kumpulkan kayu bakar tambahan', 'Periksa barang bawaan kapal karam'];
}

return { json: { content: reply, chips: chips } };
